INSERT INTO public.curriculum_framework_refs
  (framework, code, title, lang, level, group_code, group_title, examples, guidance, source, sort_order)
VALUES
  ('nush-ifo-2018', '2 ІФО 1.1.1', 'Пояснює сприйняття інформації різними органами чуття на основі власних спостережень', 'uk', '1-2', 'ІФО 1.1', 'Досліджує і оцінює вплив інформаційних технологій на своє життя, навколишній світ і розвиток', '["Опишіть, що ви бачите, чуєте та відчуваєте на дотик під час прогулянки шкільним подвір’ям.","Назвіть кілька прикладів інформації, яку ви отримали сьогодні (з книжки, розмови, картинки), та поясніть, чому вона для вас важлива.","Розкладіть картки за тим, яким органом чуття можна отримати цю інформацію, та порівняйте групи.","Створіть малюнок, символ або покажіть жест, щоб передати певне повідомлення однокласникам.","Розіграйте в парах сценку, де один учень передає інформацію, а інший її отримує."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 1),
  ('nush-ifo-2018', '2 ІФО 1.2.1', 'Розрізняє та фіксує дані, аналізує та впорядковує прості послідовності', 'uk', '1-2', 'ІФО 1.2', 'Знаходить, збирає, зберігає, представляє, перетворює, структурує, аналізує і узагальнює дані різних типів', '["Знайдіть інформацію про погоду наступного тижня у вашому населеному пункті. Визначте, яка температура буде протягом тижня вночі та вдень.","Запишіть отримані відомості в зошиті в таблицю за зразком учителя (дата, день тижня, температура вночі, температура вдень). Відтворіть таку таблицю в текстовому редакторі в наданому шаблоні.","Визначте за даними таблиці, у який день буде найбільша та найменша температура вночі та вдень. Позначте найбільші й найменші значення різними кольорами.","Розташуйте надані предмети (геометричні фігури) за розміром. Знайдіть серед них зайвий. Запропонуйте, яким предметом можна доповнити перелік.","Намалюйте отриманий ряд фігур. Відтворіть це зображення у графічному редакторі."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 2),
  ('nush-ifo-2018', '2 ІФО 1.3.1', 'Визначає об’єкти, їх властивості та значення властивостей за підтримки вчителя; розрізняє моделі та їх відповідники у реальному світі, створює прості моделі', 'uk', '1-2', 'ІФО 1.3', 'Будує інформаційні моделі об’єктів, явищ і процесів', '["За описом об’єкта вкажіть його назву (наприклад, «сірий, ікластий, хоче вівцю вкрасти», «нежива, але має 5 пальців»). Опишіть властивості цих об’єктів.","Вкажіть, моделями яких реальних об’єктів є глобус, лялька, іграшковий автомобіль.","Намалюйте модель будь-якого природного явища."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 3),
  ('nush-ifo-2018', '2 ІФО 1.4.1', 'Розрізняє правдиві та неправдиві твердження, здобуті з різних джерел', 'uk', '1-2', 'ІФО 1.4', 'Критично оцінює інформацію, отриману з різних джерел', '["Визначте, які з наведених тверджень є неправдивими, і поясніть чому: «Якщо з’їсти морозиво взимку, обов’язково захворієш», «Пінгвіни живуть на Північному полюсі», «Якщо довго не мити руки, мікроби на них можуть спричинити хворобу» тощо.","Пограйте в гру: вигадайте правдиве або неправдиве твердження та перекажіть його однокласнику/однокласниці. Він/вона має визначити, чи правдиве твердження. Потім поміняйтеся ролями."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 4),
  ('nush-ifo-2018', '2 ІФО 2.1.1', 'Створює план дій, наводить приклади повторення та виконання дій за визначеним завданням у повсякденній діяльності', 'uk', '1-2', 'ІФО 2.1', 'Розробляє і реалізовує алгоритми', '["Розкладіть малюнки у правильному порядку, щоб показати, як одягатися взимку.","Складіть усний план того, що ви робите зранку перед школою, у правильній послідовності.","Обговоріть, що може статися, якщо переплутати порядок дій, наприклад одягнути взуття перед шкарпетками.","Розіграйте сценку на пішохідному переході, виконуючи кроки для безпечного переходу дороги."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 5),
  ('nush-ifo-2018', '2 ІФО 2.2.1', 'Складає простий план із точних та однозначних вказівок до дій виконавців, виявляє в ньому помилки, оцінює відповідність очікуваному результату', 'uk', '1-2', 'ІФО 2.2', 'Створює і налагоджує програмні проєкти', '["Складіть усний план створення листівки: «Спочатку обери фон → потім встав малюнок → додай текст». Обговоріть, що зміниться, якщо порядок дій буде іншим.","Опишіть послідовність дій для поєднання малюнка та голосового повідомлення: «Записати звук → вставити малюнок → з’єднати разом». Спробуйте змінити порядок і порівняйте результат.","Визначте кроки для створення слайда з фотографіями: «Вставити фото → підписати → зберегти». Замініть один крок або змініть порядок та поясніть, що сталося."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 6),
  ('nush-ifo-2018', '2 ІФО 2.3.1', 'Складає ціле із запропонованих частин, пояснює, як заміна окремих частин приводить до іншого цілого', 'uk', '1-2', 'ІФО 2.3', 'Розробляє модульні проєкти', '["Об’єднайтеся в пари чи групи та складіть алгоритм створення спільного малюнка або листівки: хто що робить та в якій послідовності. Після цього реалізуйте його на практиці.","Разом підготуйте коротке повідомлення для шкільної газети чи стінгазети, але спочатку складіть покрокову інструкцію-алгоритм: збір інформації → написання тексту → додавання малюнка → оформлення."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 7),
  ('nush-ifo-2018', '2 ІФО 2.4.1', 'Використовує готові та створює прості інформаційні продукти (текст, зображення, звуки) для отримання, передачі інформації або представлення власних ідей, результатів діяльності', 'uk', '1-2', 'ІФО 2.4', 'Створює та опрацьовує інформаційні продукти з використанням даних різних типів', '["Створи привітання для однокласника у текстовому редакторі.","Ілюструй власну казку або розповідь за допомогою малюнків.","Впізнай звуки (тварин, транспорту) та підбери відповідні зображення.","Створи слайд-презентацію: малюнок своєї родини, короткий підпис і запис власного голосу."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 8),
  ('nush-ifo-2018', '2 ІФО 2.5.1', 'Самостійно та відповідально виконує визначені завдання; працює в команді з іншими особами для досягнення спільної мети', 'uk', '1-2', 'ІФО 2.5', 'Співпрацює в команді для створення інформаційного продукту', '["Намалюй пелюстку квітки для групового проєкту «Наші правила». Напиши у своїй пелюстці одне з правил, які ви обговорили та визначили в групі."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 9),
  ('nush-ifo-2018', '2 ІФО 3.1.1', 'Використовує цифрові пристрої вдома, у школі, на вулиці та пояснює їх призначення', 'uk', '1-2', 'ІФО 3.1', 'Використовує широкий спектр цифрових пристроїв', '["Намалюйте або складіть колаж, що показує ваші цифрові пристрої та для чого ви їх використовуєте.","Розкладіть на макеті робочого місця картинки з предметами й пристроями так, щоб ними було зручно користуватися.","Виконайте вправу з навігації: відкрийте фото у галереї, перегляньте наступне, поверніться назад.","Порівняйте друковану та електронну книгу: чим вони схожі й чим відрізняються."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 10),
  ('nush-ifo-2018', '2 ІФО 3.2.1', 'Організовує власне робоче місце за допомогою дорослих; розпізнає та описує прості проблеми та збої, які виникають у роботі доступних цифрових пристроїв, звертається за допомогою та підтримкою', 'uk', '1-2', 'ІФО 3.2', 'Організовує власне інформаційне середовище', '["Розташуйте за допомогою вчителя чи батьків стілець, стіл і пристрої так, щоб було зручно та безпечно працювати.","Покажіть дорослому, де знаходиться кнопка увімкнення комп’ютера чи планшета.","Назвіть частини пристрою, якими ви користуєтесь: екран, мишка, клавіатура, зарядний пристрій.","Опишіть простими словами, що сталося, коли пристрій «не слухається»: не вмикається, немає звуку, не працює інтернет.","Покажіть дорослому, що саме не працює, використовуючи жести або малюнок.","Запитайте про допомогу, коли ви не знаєте, як виправити проблему.","Разом із дорослим перевірте, чи підключений пристрій до електрики або чи заряджена батарея."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 11),
  ('nush-ifo-2018', '2 ІФО 3.3.1', 'Використовує цифрові пристрої, технології для доступу до інформації та спілкування', 'uk', '1-2', 'ІФО 3.3', 'Використовує комунікаційні технології та мережі для власного розвитку, спілкування і співпраці', '["Увімкніть планшет або комп’ютер і знайдіть значок потрібної програми для спілкування, наприклад відеозв’язку з учителем.","Відкрийте навчальний сайт або додаток за вказівкою вчителя.","Надішліть коротке повідомлення однокласнику чи вчителю з підготовленим текстом або емодзі.","Покажіть, як знайти потрібне зображення чи інформацію у дитячій пошуковій системі за допомогою дорослого.","Використайте камеру для фотографування або відеозапису малюнка чи виробу, щоб поділитися з класом.","Відкрийте електронну книгу або навчальне відео, перемкніть сторінки чи частини відео за інструкцією.","Вимкніть пристрій після завершення роботи, дотримуючись правил безпеки."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 12),
  ('nush-ifo-2018', '2 ІФО 4.1.1', 'Дотримується правил безпечної роботи; захищає власний інформаційний простір; розповідає про проблеми дорослим', 'uk', '1-2', 'ІФО 4.1', 'Обґрунтовує вплив технологій на навколишнє середовище і власний добробут, захищає себе і свій інформаційний простір', '["Серед запропонованих зображень позначте те, яке описує ситуацію безпечного використання пристроїв."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 13),
  ('nush-ifo-2018', '2 ІФО 4.2.1', 'Зважає на технічні можливості цифрових пристроїв для спілкування, зокрема з людьми з особливими потребами, поважає приватність повідомлень, толерантно ставиться до відмінностей культур, традицій і різних думок', 'uk', '1-2', 'ІФО 4.2', 'Усвідомлено дотримується норм соціальної, міжкультурної і міжособистісної взаємодії', '["Напишіть повідомлення другу/подрузі про святкування дня народження так, щоб його могли зрозуміти всі, воно було приватним і ввічливим, поважало різні традиції та думки."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 14),
  ('nush-ifo-2018', '2 ІФО 4.3.1', 'Зазначає авторство власних робіт; виявляє повагу до авторства інших осіб', 'uk', '1-2', 'ІФО 4.3', 'Усвідомлено дотримується норм правової взаємодії', '["Створіть власні інформаційні продукти з підписом: малюнки, фото, презентації.","Обговоріть ситуації — історії, казки, мінісценки — про чесність і списування.","Працюйте з простими джерелами, наприклад підписаними малюнками з дитячих сайтів, та визначте автора."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 1-2 класи («Інтерактивний поступ»)', 15),
  ('nush-ifo-2018', '4 ІФО 1.1.1', 'Пояснює основні інформаційні процеси у близькому для себе середовищі (дім, школа, вулиця) на основі власних спостережень', 'uk', '3-4', 'ІФО 1.1', 'Досліджує і оцінює вплив інформаційних технологій на своє життя, навколишній світ і розвиток', '["Розгляньте приклади текстів, малюнків, відео та звуків і визначте, яким способом вони подані та як їх можна сприйняти.","Наведіть приклади інформації, яка допомогла вам у навчанні чи побуті, та поясніть, чому вона була важливою.","Опишіть, як відбувається обмін повідомленнями під час підготовки класного заходу, і хто є учасниками цього процесу.","Порівняйте, як ви навчаєтесь, спілкуєтесь або розважаєтесь з використанням комп’ютера чи телефона та без них, і зробіть висновок, що змінилося б без цих технологій."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 16),
  ('nush-ifo-2018', '4 ІФО 1.2.1', 'Знаходить інформацію, зберігає дані на цифрових носіях, перетворює інформацію з однієї форми в іншу за допомогою поданих шаблонів, порівнює різні способи представлення інформації, аналізує та впорядковує послідовності', 'uk', '3-4', 'ІФО 1.2', 'Знаходить, збирає, зберігає, представляє, перетворює, структурує, аналізує і узагальнює дані різних типів', '["Знайдіть текстову інформацію та зображення улюбленої тваринки. Збережіть знайдену інформацію на робочому комп’ютері.","Зніміть відео про свою домашню тваринку та відправте його своїм батькам і вчителю в месенджері.","Закодуйте в зошиті назву своєї тваринки за правилом (літера замінюється на її номер в абетці).","Розкодуйте назви улюбленців ваших однокласників.","Придумайте ребус з назвою улюбленої тваринки і створіть його в презентації.","Проведіть опитування учнів у класі про те, які домашні тваринки у них є. Впорядкуйте результати опитування за зростанням.","Намалюйте стовпчасту діаграму за результатами опитування. Дайте відповіді на запитання: яких тваринок найбільше, а яких найменше?"]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 17),
  ('nush-ifo-2018', '4 ІФО 1.3.1', 'Класифікує об’єкти за їх властивостями, зіставляє ознаки моделей реального і цифрового світу, аналізує вплив подій на властивості, досліджує об’єкти за допомогою створених моделей', 'uk', '3-4', 'ІФО 1.3', 'Будує інформаційні моделі об’єктів, явищ і процесів', '["Розподіліть об’єкти за двома групами (наприклад, 4 червоних об’єкти і 3 квадратних). Поясніть, за якими властивостями було віднесено об’єкти до кожної групи і якими були значення цих властивостей.","Створіть наочну модель — паперовий літачок. На одному крилі запишіть істотні властивості реального об’єкта, які було залишено в моделі, а на іншому — властивості, які в моделі не враховувалися. Яку дію реального об’єкта здатна виконувати створена модель? Перевірте, як вона працює."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 18),
  ('nush-ifo-2018', '4 ІФО 1.4.1', 'Висловлює припущення про достовірність інформації, отриманої з цифрових джерел, розрізняє факти і судження', 'uk', '3-4', 'ІФО 1.4', 'Критично оцінює інформацію, отриману з різних джерел', '["Визначте, які з наведених тверджень є фактами, а які — судженнями. Оцініть їхню достовірність. «Завтра точно піде сніг, бо так сказав популярний блогер», «Цей напій зробить тебе найсильнішим у класі», «Згідно з інформацією на сайті sinoptik.ua, сонце завтра зійде о 7:48» тощо.","Подумайте, інформація з яких джерел є більш або менш достовірною: почута від друга; опублікована у Вікіпедії; опублікована у шкільному каналі в месенджері тощо."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 19),
  ('nush-ifo-2018', '4 ІФО 2.1.1', 'Розробляє алгоритми (зокрема, для власної чи групової діяльності) з послідовних дій, умов, повторень', 'uk', '3-4', 'ІФО 2.1', 'Розробляє і реалізовує алгоритми', '["Складіть алгоритм з карток або блок-схем, щоб показати, як приготувати бутерброд.","Візьміть участь у грі «логічний маршрут», склавши інструкції для досягнення певної цілі та виконавши їх.","Виконайте завдання за умовою: «якщо йде дощ — візьми парасольку».","Разом у групі складіть алгоритм прибирання класної кімнати та перевірте його виконання."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 20),
  ('nush-ifo-2018', '4 ІФО 2.2.1', 'Створює згідно з планом або алгоритмом прості програми та налагоджує їх; прогнозує та формулює очікуваний результат створеної програми', 'uk', '3-4', 'ІФО 2.2', 'Створює і налагоджує програмні проєкти', '["Складіть алгоритм руху виконавця (робота, іграшки чи аватара) за маршрутом і перевірте, що станеться при зміні кроків.","Опишіть план вимірювання довжини класної кімнати: підготовка інструменту, відлік, фіксація результату. Обговоріть наслідки пропуску кроку.","Складіть алгоритм розв’язання математичної задачі: прочитати умову → виконати дію → перевірити результат.","Розробіть послідовність збору даних про погоду: вимірювання → запис → таблиця → діаграма.","Порівняйте алгоритми у створенні презентації, русі робота та вимірюваннях, визначте спільні риси."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 21),
  ('nush-ifo-2018', '4 ІФО 2.3.1', 'Розкладає задачі на прості, які виконуються згідно з окремими інструкціями чи послідовністю інструкцій і навпаки (компонує)', 'uk', '3-4', 'ІФО 2.3', 'Розробляє модульні проєкти', '["Створіть малюнок із готових форм. Опишіть кроки (алгоритм), як ви це зробили. Змініть одну форму й подивіться, що змінилося.","Зробіть слайд-привітання з трьох елементів (текст, картинка, фон). Запишіть послідовність дій. Замініть фон і порівняйте результат.","Складіть пазл із частин. Визначте порядок складання (алгоритм). Змініть одну деталь і поясніть, чи треба змінювати порядок.","Придумайте маршрут для робота. Намалюйте схему руху робота по клітинках (наприклад, «вперед — вперед — поверни праворуч»). Змініть одну команду й подивіться, як змінився маршрут."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 22),
  ('nush-ifo-2018', '4 ІФО 2.4.1', 'Створює інформаційні продукти, поєднуючи текст, зображення, звук тощо для представлення ідей та/або результатів діяльності', 'uk', '3-4', 'ІФО 2.4', 'Створює та опрацьовує інформаційні продукти з використанням даних різних типів', '["Створи мультимедійну презентацію на тему «Моя родина».","Склади інструкцію «Як приготувати канапку» з фото, підписами до кожного кроку та короткими звуковими підказками.","Створи колаж на тему «Мої мрії» за допомогою зображень з бібліотеки й підписів до кожної мрії."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 23),
  ('nush-ifo-2018', '4 ІФО 2.5.1', 'Керує своїми діями та пояснює власний внесок у спільний результат роботи команди, коментує успішні та невдалі кроки у процесі роботи', 'uk', '3-4', 'ІФО 2.5', 'Співпрацює в команді для створення інформаційного продукту', '["У групі оберіть тваринку, яка потребує захисту, та складіть план презентації про неї. Оберіть пункт плану та реалізуйте його. Перегляньте інші слайди та надайте поради учасникам та учасницям групи, як удосконалити презентацію."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 24),
  ('nush-ifo-2018', '4 ІФО 3.1.1', 'Обирає цифрове середовище, пристрої, засоби для розв’язання життєвої задачі/проблеми, пояснює свій вибір', 'uk', '3-4', 'ІФО 3.1', 'Використовує широкий спектр цифрових пристроїв', '["Упорядкуйте цифрові середовища за призначенням (для перегляду, для створення, для обговорення, для збереження інформації).","Змоделюйте власне цифрове середовище: складіть список пристроїв, програм і ресурсів, які використовуєте для різних цілей.","Дослідіть налаштування програми відповідно до потреб (наприклад, розмір шрифту, вибір мови, гучність).","Складіть алгоритм дій створення цифрового об’єкта (наприклад, малюнка чи фото), його збереження та передавання іншій людині."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 25),
  ('nush-ifo-2018', '4 ІФО 3.2.1', 'Налаштовує для власних потреб відповідне програмне середовище; визначає за допомогою правильної термінології збої у роботі доступних цифрових пристроїв, усуває прості несправності', 'uk', '3-4', 'ІФО 3.2', 'Організовує власне інформаційне середовище', '["Упорядкуйте Робочий стіл: створіть папку «Мої роботи», перейменуйте файли за зразком «Дата_Тема».","Створіть додаткові тематичні папки (наприклад, «Фото», «Презентації», «Домашні завдання») та розмістіть у них відповідні файли.","У текстовому редакторі встановіть бажаний шрифт, розмір і колір тексту для зручності читання.","У графічному редакторі виберіть колірну палітру, яка вам подобається, і збережіть її для повторного використання.","У редакторі презентацій виберіть тему оформлення та налаштуйте кольори слайдів.","Налаштуйте мову інтерфейсу та розкладку клавіатури (UA/EN) і перевірте введення.","Визначте ситуації за термінами: «зависання програми», «повільна робота», «помилка підключення до мережі», «відсутній звук», «некоректне введення (розкладка/Caps Lock)», «розряджений акумулятор», «несправне підключення пристрою».","Опишіть збій коротко; наприклад: «Після відкриття редактора з’являється повідомлення про помилку — файл не зберігається».","Заповніть міні-заявку щодо збоїв у роботі комп’ютера (можна оформити у текстовому редакторі): «До кого ця заявка? Що сталося? Де? Коли? Що вже пробували?»."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 26),
  ('nush-ifo-2018', '4 ІФО 3.3.1', 'Співпрацює та спілкується в захищених мережевих спільнотах для обміну думками, виконання спільних завдань, пошуку інформації та навчання', 'uk', '3-4', 'ІФО 3.3', 'Використовує комунікаційні технології та мережі для власного розвитку, спілкування і співпраці', '["Опублікуйте у спільній групі повідомлення або фото, пов’язані з навчальним завданням. Відповідайте на коментарі однокласників, підтримуючи правила ввічливого спілкування.","Створіть у групі повідомлення, у якому поділитеся ідеєю для спільного завдання, використовуючи ввічливі звертання.","Перевірте повідомлення однокласника на наявність особистих даних (прізвище, адреса, телефон) та запропонуйте спосіб, як залишити зміст, але зробити його безпечним.","Візьміть участь у рольовій грі «Модератор спільноти», у якій потрібно відсортувати повідомлення: які можна публікувати, а які — ні, пояснюючи свій вибір.","Знайдіть у безпечній пошуковій системі зображення або текст, потрібні для спільного завдання, і поділіться посиланням у групі.","Об’єднайтеся в пари, щоб зібрати інформацію з різних джерел на задану тему, а потім обговоріть у чаті спільноти, які матеріали варто використати."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 27),
  ('nush-ifo-2018', '4 ІФО 4.1.1', 'Відповідально використовує технології для власної безпеки, регулює власний час роботи з цифровими пристроями, обговорює різні наслідки використання інформаційних технологій у школі, на вулиці, вдома тощо', 'uk', '3-4', 'ІФО 4.1', 'Обґрунтовує вплив технологій на навколишнє середовище і власний добробут, захищає себе і свій інформаційний простір', '["Поділіть аркуш на дві частини: «користь» і «шкода». Запишіть по 3 приклади, як інформаційні технології допомагають у школі (наприклад: пошук інформації, презентація), та як вони можуть зашкодити вдома чи на вулиці (наприклад: залежність від ігор, забування про домашні справи). Обговоріть результати у групі, а потім зробіть висновок: як користуватися технологіями так, щоб було більше користі, ніж шкоди."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 28),
  ('nush-ifo-2018', '4 ІФО 4.2.1', 'Добирає належні засоби для спілкування з іншими особами, зокрема з людьми з особливими потребами, безпосередньо та через Інтернет, усвідомлює відповідальність за свою діяльність в Інтернеті; рекомендує цікаві та безпечні веб-сайти своїм друзям', 'uk', '3-4', 'ІФО 4.2', 'Усвідомлено дотримується норм соціальної, міжкультурної і міжособистісної взаємодії', '["Порадьте друзям цікавий і безпечний сайт для навчання або розвитку, який враховує потребу у зміні розміру шрифту на екрані."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 29),
  ('nush-ifo-2018', '4 ІФО 4.3.1', 'Відвідує тільки корисні і безпечні веб-сайти; дотримується правил використання власних і чужих творів', 'uk', '3-4', 'ІФО 4.3', 'Усвідомлено дотримується норм правової взаємодії', '["Створіть презентацію або афішу з використанням зображень, знайдіть і вкажіть джерела.","Обговоріть, чому не можна копіювати чужу роботу та чому слід уникати сумнівних сайтів.","Виконайте вправу «Знайдіть помилку»: проаналізуйте приклад роботи без джерел та вкажіть на порушення.","Підготуйте «свідоцтво автора» для своєї роботи з поясненням, чому важливо зазначати авторство."]'::jsonb, NULL, 'МОН, Інформатична освітня галузь, цикл 3-4 класи («Інтерактивний поступ»)', 30),
  ('cambridge-0059', '1CT.01', 'Follow the steps in algorithms for everyday tasks.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 31),
  ('cambridge-0059', '1CT.02', 'Identify single errors in algorithms that represent everyday events or tasks.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 32),
  ('cambridge-0059', '1CT.03', 'Know how to give simple instructions, using directional language (forward, backwards, left, right), to navigate a path.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 33),
  ('cambridge-0059', '1CT.04', 'Suggest sets of ordered instructions to complete simple tasks, such as drawing a picture of a particular object or building a brick tower.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 34),
  ('cambridge-0059', '1CT.05', 'Know that an algorithm is a set of instructions to complete a task or to solve a problem.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 35),
  ('cambridge-0059', '1CT.06', 'Know that the order of instructions is important when creating algorithms.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 36),
  ('cambridge-0059', '1CT.07', 'Suggest ways that algorithms can be changed to affect the outcome.', 'en', '1', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 37),
  ('cambridge-0059', '1P.01', 'Know that algorithms can be recreated as code on computers.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 38),
  ('cambridge-0059', '1P.02', 'Know how to recreate algorithms as programs to perform simple tasks.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 39),
  ('cambridge-0059', '1P.03', 'Predict what is likely to happen when programs are run.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 40),
  ('cambridge-0059', '1P.04', 'Know that programs can contain errors.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 41),
  ('cambridge-0059', '1P.05', 'Know how to run programs to test whether they produce the desired result.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 42),
  ('cambridge-0059', '1P.06', 'Identify why a program does not produce the desired result.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 43),
  ('cambridge-0059', '1P.07', 'Know that ''debugging'' is the correction of errors in programs.', 'en', '1', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 44),
  ('cambridge-0059', '1MD.01', 'Know that computing devices can be used in different ways to answer many different types of question.', 'en', '1', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 45),
  ('cambridge-0059', '1MD.02', 'Know that computing devices can help to sort and organise data.', 'en', '1', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 46),
  ('cambridge-0059', '1MD.03', 'Know how to use computing devices to manually record data, including using a form.', 'en', '1', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 47),
  ('cambridge-0059', '1MD.04', 'Identify questions that can be answered using data tables, limited to categorical data.', 'en', '1', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 17', 48),
  ('cambridge-0059', '1DC.01', 'Know that some devices can connect to each other to make a network.', 'en', '1', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 49),
  ('cambridge-0059', '1DC.02', 'Know that the internet consists of many computers that are connected together around the world.', 'en', '1', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 50),
  ('cambridge-0059', '1DC.03', 'Identify that some devices are connected by wires and that other devices are not.', 'en', '1', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 51),
  ('cambridge-0059', '1DC.04', 'Know that there are times when the internet is not available.', 'en', '1', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 52),
  ('cambridge-0059', '1CS.01', 'Know that there are a range of computer systems with different functions, including communication, entertainment, creativity, research and for controlling other technology.', 'en', '1', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 53),
  ('cambridge-0059', '1CS.02', 'Know that computers can run many different programs, including games, apps and document creation tools.', 'en', '1', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 54),
  ('cambridge-0059', '1CS.03', 'Know that information and data can be input to computers in many different ways.', 'en', '1', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 55),
  ('cambridge-0059', '1CS.04', 'Know that computers can output information in many different ways.', 'en', '1', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 56),
  ('cambridge-0059', '1CS.05', 'Know that there are many everyday devices that use computers to control what they do.', 'en', '1', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 57),
  ('cambridge-0059', '1CS.06', 'Identify what robots are and where they may be found in the real world.', 'en', '1', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 18', 58),
  ('cambridge-0072', '1TC.01', 'Know how to switch on and log on to a digital device using a password.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: ‘logon’, ‘log on’ and ‘password’ Expectation: Give learners repeated opportunities to start up devices, but require them to seek permission before doing so. Other guidance: Passwords might be generic at this stage.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 59),
  ('cambridge-0072', '1TC.02', 'Explore how to interact with onscreen items through clicking, tapping, dragging, dropping, scrolling, and swiping.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Explore as many of the interaction types as possible. Other guidance: Requires exploration of different device types (computers, tablets) and different platforms (websites, games, productivity software).', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 60),
  ('cambridge-0072', '1TC.03', 'Explore inputting familiar words into text processing software, using a range of input devices including typing and voice.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: input Expectation: Enter words using phonetic understanding, i.e. Consonant-Vowel-Consonant (CVC) words. Type one letter at a time. Other guidance: Re-enter words for keyboard familiarisation. Repeat using voice to text software, comparing the experience and the outcome.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 61),
  ('cambridge-0072', '1TC.04', 'Access, explore and interact with AI platforms, commenting on experiences and outcomes.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Use instructions to explore appropriate chatbots and AI games. Other guidance: Share and discuss pleasing and frustrating experiences.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 62),
  ('cambridge-0072', '1TC.05', 'Give clear and specific prompts when asking for human help with using a digital tool, such as when searching, navigating, or creating.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: prompt Expectation: Use verbal prompts in the form of short sequences of instruction at this stage. Other guidance: The supporting adult should follow the prompts as they are given and support learners to make necessary refinements.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 63),
  ('cambridge-0072', '1TC.06', 'Understand the purpose of prompting and explore how prompts can be given to digital and AI tools.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Explore how answers to simple questions can be found by giving spoken and/or typed prompts to digital and AI platforms. Other guidance: At this stage it is likely that learners will adapt given question templates, particularly when typing. Discuss how digital and AI tools respond to prompts differently to humans.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 64),
  ('cambridge-0072', '1TC.07', 'Input common words to create prompts for AI to generate simple text outputs, including coherent sentences, and outputs in other modes, such as images.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Identify that AI does not just answer questions. Use spoken or typed prompts to generate outputs such as images, and audio and onscreen sentences.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 65),
  ('cambridge-0072', '1TC.08', 'Know that AI gets information from large amounts of data, including from the web, internet and many other digital and non-digital sources.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: data, web (World Wide Web), internet Expectation: Understand ‘data’ in familiar contexts, such as lunchbox items. Discuss how AI outputs are never entirely new.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 66),
  ('cambridge-0072', '1TC.09', 'Explore how to open and save digital files, and the purposes of doing this.', 'en', '1', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: file, open, save Expectation: Compare file saving with human memory and with physical storage. Explore the process of file opening and saving, for example on the school network, using simple but easily identifiable file names.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 67),
  ('cambridge-0072', '1SW.01', 'Know what a password is and describe why they are vital.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Vocabulary: password, and variations such as ‘passcode’ where appropriate Expectation: Explore the importance of locking devices when not using them. Other guidance: Consider in the context of protecting physical items and personal data.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 68),
  ('cambridge-0072', '1SW.02', 'Know how to report digital content or activity that makes them feel unsafe or uncomfortable.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Agree protocols. Understand that dangers in digital contexts cannot be easily observed by adults. Other guidance: Explore in the context of feeling physically unsafe. Age-appropriate unexpected activity might include web content, pop-ups or the device freezing.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 69),
  ('cambridge-0072', '1SW.03', 'Identify examples of personal information that should never be shared online in any context.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Identify data that should never be shared, including understanding the risks of doing so. Other guidance: Learners might begin to make links between two data items, such as home address and family holiday dates.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 70),
  ('cambridge-0072', '1SW.04', 'Understand why rules apply to the use of digital and AI devices, including those related to overuse, purpose, and health and safety.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Include topics such as screentime limits, physical sharing, safety and seeking permission. Learners begin to understand that some activities are more valuable, or present greater risks, than others. Other guidance: If applicable, explore the school’s acceptable use policy.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 71),
  ('cambridge-0072', '1SW.05', 'Identify reasons why digital device use should be limited, including that they should be used for specific activities.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Identify the benefits of other activity, including physical movement, social interaction and a wider range of stimuli.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 72),
  ('cambridge-0072', '1SW.06', 'Identify benefits and drawbacks of different forms of play and participation in digital worlds, including on a range of solitary and collaborative platforms.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Begin to differentiate between digital activities that require participation and those that are passive. Explore how challenge is good for development and wellbeing.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 73),
  ('cambridge-0072', '1SW.07', 'Identify potential positive and negative influences of using digital and AI-powered tools.', 'en', '1', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Understand that ‘influences’ are experiences, or people, that help humans decide what they like or what to do. Other guidance: Positive influences might include aspects of learning support and relaxation. Negatives might include those that generate feelings of anxiety or frustration, such as when a device is taken away or when the tool does not respond as expected.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 16', 74),
  ('cambridge-0072', '1DW.01', 'Explore activities that can be done with and without computers, and describe the differences between digital and non-digital experiences.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Understand that there are activities that can be done with or without computers, appreciating that this creates choice. Other guidance: Example activities include mark or music making, text creation, gameplay and listening to stories.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 75),
  ('cambridge-0072', '1DW.02', 'Know that ‘AI’ is a common term for Artificial Intelligence, that AI systems can think and learn, and that this is sometimes similar to how humans think and learn.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: Artificial Intelligence (AI), system, artificial Expectation: Make age-appropriate comparison between the things that familiar AI tools can do and human intelligence. Outline the decision- making processes followed by the AI. Other guidance: Explore the word ‘artificial’. Conclusions might include that AI is convenient but that human intelligence has a much wider range, including in an emotional context.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 76),
  ('cambridge-0072', '1DW.03', 'Identify AI tools in familiar contexts, including their purpose.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Develop an early awareness of where AI exists in familiar contexts. Other guidance: Examples include voice assistants, online shopping platforms, satellite navigation, games, smartphones and streaming services.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 77),
  ('cambridge-0072', '1DW.04', 'Identify artefacts that have, and have not, been created digitally, while expressing reasoned preferences.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Focus on the role of consumer, rather than creator. Compare personal responses to human outputs, such as art and stories, with similar items that have been created digitally, including by AI.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 78),
  ('cambridge-0072', '1DW.05', 'Explore how the internet provides access to many services, including streaming services and content that is presented on interconnected websites and pages.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: internet, website Expectation: Contrast services that are built into a device with those that are only available online. Understand that some services are not available if the device is unable to connect to the internet.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 79),
  ('cambridge-0072', '1DW.06', 'Explore what chatbots are and what they do, and identify that they only respond if they are prompted to do so.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: chatbot Expectation: Explore processes for obtaining responses from chatbots. Other guidance: Reflection includes deciding whether the output matches the intention.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 80),
  ('cambridge-0072', '1DW.07', 'Explore how AI learns by being given, and processing, lots of data types, including words, pictures and numbers.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: data Expectation: Begin to understand the range, scale and sources of data used to train AI systems. Other guidance: Learners might work in small groups to gather data about the personal interests of each group member, such as favourite toy and favourite physical activity, to create a description of a ‘typical’ group member. Through doing this they begin to understand that reliance on data does not produce perfect outcomes. For example, the output might suggest that all the group members like football, when this was only selected by two of them.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 81),
  ('cambridge-0072', '1DW.08', 'Identify the tasks that digital and AI tools are used for at home.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Demonstrate early recognition by identifying familiar tools and their purpose. Other guidance: Examples might include voice assistants, control devices such as for lights, appliances such as fridges, entertainment systems and cleaning robots. Learners might mark an outline map of their home to represent the location of each tool. They should discuss reasons why their map should not be shared with strangers.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 82),
  ('cambridge-0072', '1DW.09', 'Identify opportunities that are available to humans through digital device use.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Consider familiar tools, and possible new encounters, in terms of benefits and opportunities, such as learning, time saving, problem solving and enjoyment.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 83),
  ('cambridge-0072', '1DW.10', 'Identify potential barriers to digital opportunities, including temporary and permanent barriers.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: As well as considering device access, explore reasons why devices might be ‘connected’ at some times but not at others. Other guidance: This requires sensitivity as learners discuss examples of where digital devices might not be available in local contexts, such as due to affordability.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 84),
  ('cambridge-0072', '1DW.11', 'Explore ways that digital worlds invite play and creativity.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Positively explore inspiration and encourage learners to think aloud while they play or create. Retain awareness of the need to balance digital and non-digital activity. Other guidance: An example observation might be the excitement, determination and perseverance generated by digital gameplay. Learners might also identify that creative risk taking is supported through the ease of trialling ideas and then deleting, or ‘undoing’, any experiments that do not match the intention.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 85),
  ('cambridge-0072', '1DW.12', 'Compare and contrast the emotional influence of AI outputs with interaction with other humans.', 'en', '1', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Contrast many dimensions of human expression, as demonstrated by family members, with less dimensional, or inanimate, AI and digital tools. Other guidance: This could be explored through roleplay.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 17', 86),
  ('cambridge-0059', '2CT.01', 'Follow and understand linear algorithms.', 'en', '2', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 87),
  ('cambridge-0059', '2CT.02', 'Identify and correct a single error in algorithms that represent everyday events or tasks.', 'en', '2', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 88),
  ('cambridge-0059', '2CT.03', 'Know that an algorithm is a precise set of instructions.', 'en', '2', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 89),
  ('cambridge-0059', '2CT.04', 'Identify the steps needed to undertake tasks, in order to develop simple algorithms.', 'en', '2', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 90),
  ('cambridge-0059', '2CT.05', 'Predict the outputs of algorithms.', 'en', '2', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 91),
  ('cambridge-0059', '2CT.06', 'Know how to develop precise sets of instructions to complete simple tasks, such as drawing a picture of a particular object or building a brick tower.', 'en', '2', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 92),
  ('cambridge-0059', '2P.01', 'Understand that programs instruct computers how to run algorithms.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 93),
  ('cambridge-0059', '2P.02', 'Know how to recreate algorithms as programs.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 94),
  ('cambridge-0059', '2P.03', 'Know how to develop programs to produce desired outputs, including the use of the repeat command.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 95),
  ('cambridge-0059', '2P.04', 'Know how to plan the instructions for objects within programs.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 96),
  ('cambridge-0059', '2P.05', 'Understand the benefits of working with others when debugging programs.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 97),
  ('cambridge-0059', '2P.06', 'Identify the benefits of regularly testing programs throughout their development.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 98),
  ('cambridge-0059', '2P.07', 'Know how to debug programs so that they will run and will produce the desired output.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 99),
  ('cambridge-0059', '2P.08', 'Know how to enter directional instructions in to a physical computing device to enable it to reach a specific destination.', 'en', '2', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 19', 100),
  ('cambridge-0059', '2MD.01', 'Know the advantages of storing data and information on computers.', 'en', '2', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 101),
  ('cambridge-0059', '2MD.02', 'Know how to use computing devices to present categorical data.', 'en', '2', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 102),
  ('cambridge-0059', '2MD.03', 'Investigate different ways of using computing devices to collect categorical data for a particular purpose.', 'en', '2', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 103),
  ('cambridge-0059', '2MD.04', 'Identify types of statistical data that can be manually recorded using computing devices.', 'en', '2', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 104),
  ('cambridge-0059', '2MD.05', 'Discuss the different types of data that a question may generate, limited to statistical and non-statistical.', 'en', '2', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 105),
  ('cambridge-0059', '2MD.06', 'Understand how data may help to solve problems.', 'en', '2', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 106),
  ('cambridge-0059', '2DC.01', 'Identify a range of devices that can connect to a network, including to the internet.', 'en', '2', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 107),
  ('cambridge-0059', '2DC.02', 'Know that two devices working together can achieve things that neither device can achieve on its own.', 'en', '2', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 108),
  ('cambridge-0059', '2DC.03', 'Know that there are wired and wireless networks.', 'en', '2', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 109),
  ('cambridge-0059', '2DC.04', 'Know how to recognise when a network is and is not available.', 'en', '2', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 110),
  ('cambridge-0059', '2DC.05', 'Know that network connected devices share information with each other and that there are risks associated with this.', 'en', '2', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 111),
  ('cambridge-0059', '2CS.01', 'Use the correct terminology to explain the functions of basic hardware and software.', 'en', '2', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 112),
  ('cambridge-0059', '2CS.02', 'Identify some features that make digital devices easy to use, including their physical parts and their functions.', 'en', '2', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 113),
  ('cambridge-0059', '2CS.03', 'Know the difference between input and output devices.', 'en', '2', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 114),
  ('cambridge-0059', '2CS.04', 'Identify tasks that computers can complete more effectively than humans.', 'en', '2', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 115),
  ('cambridge-0059', '2CS.05', 'Understand that people use different types of computer device depending on a range of factors, including their location or their purpose.', 'en', '2', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 116),
  ('cambridge-0059', '2CS.06', 'Compare the representation of robots in fiction with real robots that have a real world purpose.', 'en', '2', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 20', 117),
  ('cambridge-0072', '2TC.01', 'Explore using peripheral devices to create digitised media, including photography, audio and video.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Gradually work with decreasing support as the stage develops, using as many tools as are available. Other guidance: Learners might also begin to demonstrate autonomy when choosing the media type and/or device.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 118),
  ('cambridge-0072', '2TC.02', 'Identify common features of onscreen layouts and icons across a range of applications, including navigation symbols such as ← and →.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: icon, platform Expectation: Identify visual items that are common across a range of platforms, including websites and productivity software. Other guidance: Context could be given through exploring the origin of an icon, such as the ‘disc’ that is commonly used for saving.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 119),
  ('cambridge-0072', '2TC.03', 'Explore using voice and typing to enter words and simple sentences into different platforms, including AI.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Explore how words can be entered into different device types and platforms in different ways. Express reasoned responses for each method explored.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 120),
  ('cambridge-0072', '2TC.04', 'Identify and use editing and layout functions when creating text documents, including using modifier keys, copy, cut, paste, font formatting, margin setting, and page numbering.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: editing, layout, modifier keys, copy, cut, paste, font formatting, margin setting, page numbering. Expectation: As well as developing text creation skills, appreciate the benefit of continually exploring software in greater depth. Other guidance: As an early activity, learners might create text through speech and then read through and edit/format this, using combinations of the listed functions.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 121),
  ('cambridge-0072', '2TC.05', 'Explore the differences between using a search engine and using an AI tool to find information.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Observe that search engines return lists of links in response to questions and prompts, while AI often provides a single response, based on a combination of the available sources. Other guidance: With support, learners explore the risks of trusting either a single source or an AI summary.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 122),
  ('cambridge-0072', '2TC.06', 'Recognise the importance of giving clear prompts to search engines and AI tools.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: prompt, search engine Expectation: Explore adding clarity to prompts and search questions. Other guidance: Explore good and bad examples, before learners create prompts of their own. They can also compare the outputs with their prompts to consider simple refinements as part of an iterative process.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 123),
  ('cambridge-0072', '2TC.07', 'Explore how AI tools can help us to find information in different formats.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: With support, begin to explore how AI tools can be prompted to output information in other formats, such as images or graphics. Other guidance: Where appropriate, an AI tool could be asked to present text information visually.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 124),
  ('cambridge-0072', '2TC.08', 'Explore how AI tools can help us to find information in response to specific intentions.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: With support, learners begin to explore how AI tools can be prompted to output more than just facts. Other guidance: As an example, the audience could be described in the prompt, and learners could contrast how the outputs vary depending on differing audiences.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 125),
  ('cambridge-0072', '2TC.09', 'Explore adding specificity to prompts.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: With support, begin to explore prompt refinement. Based on reflection of initial outputs, identify simple examples of information that could be added to a prompt to achieve a more specific output.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 126),
  ('cambridge-0072', '2TC.10', 'Know how to rename digital files and move them to different locations, including to different platforms.', 'en', '2', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: (digital) file Expectation: Identify reasons for renaming and moving files before exploring platform- or network- specific procedures for doing this. Other guidance: Examples might include working in a different location, needing to share or collaborate, needing to add other media.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 127),
  ('cambridge-0072', '2SW.01', 'Explore how to set secure and memorable passwords, and understand why this is necessary.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Explore reasons why passwords should be kept secure, and should not be easy for other people to guess. Other guidance: Explore examples of insecure passwords and strategies for making them increasingly safe.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 128),
  ('cambridge-0072', '2SW.02', 'Identify examples of safe and unsafe online content or activity.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Discuss this in an age- appropriate way that is relevant to the local context. Other guidance: Teaching might involve the use of story-based scenarios.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 129),
  ('cambridge-0072', '2SW.03', 'Identify the risks of sharing personal information online.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Understand potential, age- appropriate risks to personal information, particularly in online contexts where how to manage security is not clear or obvious. Other guidance: This could be delivered through an age-appropriate scenario or role play activity. The scenario will benefit from including an aggregation of different pieces of personal data that were initially shared in different contexts, such as home address and family holiday dates.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 130),
  ('cambridge-0072', '2SW.04', 'Understand the importance of balancing screentime with other activities.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Vocabulary: screentime Expectation: Encourage a focus on wellbeing, physical activity and human interaction. Other guidance: This could be explored by listing digital and non-digital activities that learners enjoy.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 131),
  ('cambridge-0072', '2SW.05', 'Explain the difference between active and passive screentime, including the positives and negatives of both.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Vocabulary: active screentime, passive screentime Expectation: Learners begin to express strategies for effective screentime. This includes prioritising learning and productivity but also acknowledging the benefits of entertainment, enjoyment and relaxation.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 132),
  ('cambridge-0072', '2SW.06', 'Understand the need to balance fulfilment, purpose, enjoyment, wellbeing and safety when using digital tools.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Explore each of the following, with an example, in digital contexts: • Fulfilment may involve completing a task, improving an output, or reaching a new level in a game. • Purpose may focus on the production of a learning output or the exploration of a creative idea. • Enjoyment may come from gameplay, from social interaction with trusted people, from being creative or from watching a funny animation. • Wellbeing is enhanced when learners are able to recognise when, and how, to regulate their screentime. • Safety relates to risk awareness with regard to each platform.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 133),
  ('cambridge-0072', '2SW.07', 'Explore the risk that people online are not who they say they are.', 'en', '2', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Recognise that it is harder to identify strangers online than it is face to face, and that deeper critical thinking is required to decide if someone online is who they claim to be. Other guidance: Learners should prepare themselves to discuss with a trusted adult, face to face, any online interaction request from someone new or someone who cannot be easily identified.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 18', 134),
  ('cambridge-0072', '2DW.01', 'Identify the purposes of the diverse types of content that are available to users of digital and AI tools, including for information, learning, gaming and entertainment.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Explore the similarities and differences between information and learning, and between gaming and entertainment. Understand that different content appeals to different audiences.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 135),
  ('cambridge-0072', '2DW.02', 'Understand that AI can adapt to new situations but may not be as adaptable as humans.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Explore how humans are able to adapt their thoughts and actions in a range of ways when something unexpected happens, while AI might be less adaptable. Other guidance: Consider the human and AI differences through a range of ‘what if…’ scenarios.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 136),
  ('cambridge-0072', '2DW.03', 'Compare AI responses with human outputs, including text, voice, and image outputs.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Provide reasoned responses to a range of comparable human and AI responses. Other guidance: This could focus on emotion, for example how a human might be better able to demonstrate compassion through a combination of words, tone and body language. Learners might also consider how photographs and human text output can be related back to a memory or experience while an AI output does not contain the same depth.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 137),
  ('cambridge-0072', '2DW.04', 'Explore how devices can be used to communicate locally and globally, with people and with other technology, including AI.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Consider different communication methods and their most suitable applications. Other guidance: Where applicable, give learners the opportunity to consider whether they are ‘communicating’ when they are interacting with a chatbot or similar.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 138),
  ('cambridge-0072', '2DW.05', 'Know that chatbots work in different ways across AI platforms and systems, and for different purposes.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Explore different chatbots to understand how they differ in terms of input method and range of output. Other guidance: Identify, for example, that some chatbots might be limited to responding to a single context.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 139),
  ('cambridge-0072', '2DW.06', 'Know that AI processes large amounts of existing data, including from the web, internet and many other digital sources, for information about the required topics.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Understand that AI requires other sources for its information outputs; it is not able to develop theories of its own. Other guidance: Explorations of scale support understanding, such as comparing the fact that there are approximately 200 million active websites globally with the number of books in the school library. Understanding also includes that AI is not able to decide which sources are more trustworthy than others.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 140),
  ('cambridge-0072', '2DW.07', 'Understand that not all digital and technological tools use AI.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Understand that some devices only produce a single outcome type based on a specific input. Other guidance: Contrasting examples could include: • educational games that provide the player with a score and those that adapt the learning based on earlier responses • sensors that open doors when any person approaches and systems that recognise an individual’s facial features, such as when logging on to a device.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 141),
  ('cambridge-0072', '2DW.08', 'Explore how digital tools can be used to support people with particular learning or physical needs.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Consider scenarios where digital tools assist those with particular needs to identify how the tool is providing assistance, for example by converting text to speech for those with sight issues. Other guidance: Explore the use of learning platforms in particular contexts, for example mathematics games that adapt to the user’s learning needs.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 142),
  ('cambridge-0072', '2DW.09', 'Identify examples of similarities and differences between AI and human intelligence.', 'en', '2', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Reflect on their learning from across Stage 2 Digital Literacy to identify similarities and differences. Other guidance: This could be explored through small group presentations that reflect on the learning from across the stage.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 19', 143),
  ('cambridge-0059', '3CT.01', 'Follow, understand, edit and correct linear algorithms.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 144),
  ('cambridge-0059', '3CT.02', 'Understand that efficient algorithms are concise.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 145),
  ('cambridge-0059', '3CT.03', 'Identify steps that are repeated within everyday tasks.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 146),
  ('cambridge-0059', '3CT.04', 'Know that logical thinking is used in the creation of algorithms.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 147),
  ('cambridge-0059', '3CT.05', 'Predict the outcome of a change to an algorithm that is presented as a sequence of steps.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 148),
  ('cambridge-0059', '3CT.06', 'Know that many tasks can be divided into smaller sections to make them easier to follow and to edit.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 149),
  ('cambridge-0059', '3CT.07', 'Identify the inputs to algorithms.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 150),
  ('cambridge-0059', '3CT.08', 'Know how to develop linear algorithms to produce an output based on an input.', 'en', '3', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 151),
  ('cambridge-0059', '3P.01', 'Understand the benefit of editing programs to make them clear and concise, including removing unused commands or combining duplicated commands.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 152),
  ('cambridge-0059', '3P.02', 'Know how to develop programs that include code to reset objects to their original state (initialisation).', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 153),
  ('cambridge-0059', '3P.03', 'Know how to create programs with more than one algorithm running at the same time.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 154),
  ('cambridge-0059', '3P.04', 'Know how to develop programs that contain more than one object, including a static object.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 155),
  ('cambridge-0059', '3P.05', 'Know how to make a change within a block of code to achieve desired outcomes in programs, such as changing the number of steps a sprite moves.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 156),
  ('cambridge-0059', '3P.06', 'Know how to create programs to produce an output from an input device.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 157),
  ('cambridge-0059', '3P.07', 'Outline the benefits of working with others when creating programs.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 158),
  ('cambridge-0059', '3P.08', 'Understand that programmers use their mistakes to inform the programs that they create.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 159),
  ('cambridge-0059', '3P.09', 'Know how to test and debug programs so that they run and produce the desired output.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 160),
  ('cambridge-0059', '3P.10', 'Know how to develop programs for a physical computing device to produce outputs.', 'en', '3', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 21', 161),
  ('cambridge-0059', '3MD.01', 'Identify problems that can be solved through the collection and interpretation of data.', 'en', '3', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 162),
  ('cambridge-0059', '3MD.02', 'Identify and investigate different ways of representing discrete and categorical data, using a digital tool.', 'en', '3', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 163),
  ('cambridge-0059', '3MD.03', 'Know how to record discrete and categorical data, using computing devices.', 'en', '3', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 164),
  ('cambridge-0059', '3MD.04', 'Know that spreadsheets are comprised of rows and columns of cells and that data can be entered into the cells.', 'en', '3', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 165),
  ('cambridge-0059', '3MD.05', 'Know how to format cells according to their purpose, such as date, currency and text.', 'en', '3', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 166),
  ('cambridge-0059', '3MD.06', 'Demonstrate how to select data based upon their characteristics to solve problems.', 'en', '3', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 167),
  ('cambridge-0059', '3DC.01', 'Identify networked hardware in a familiar environment, including the school and home.', 'en', '3', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 168),
  ('cambridge-0059', '3DC.02', 'Identify services that are available on familiar networks, including digital files, printed documents and the World Wide Web.', 'en', '3', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 169),
  ('cambridge-0059', '3DC.03', 'Understand the advantages and disadvantages of a network.', 'en', '3', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 170),
  ('cambridge-0059', '3DC.04', 'Know that ciphers are a way of making sure that information stays secret.', 'en', '3', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 171),
  ('cambridge-0059', '3DC.05', 'Know how to write and decode messages using very simple code, including converting letters to numbers (1 = a, 2 = b, etc.).', 'en', '3', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 172),
  ('cambridge-0059', '3CS.01', 'Know that the hardware and software components of computing devices combine to form a working system.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 173),
  ('cambridge-0059', '3CS.02', 'Know the differences between hardware and software, and compare the different roles that they perform in computer systems.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 174),
  ('cambridge-0059', '3CS.03', 'Identify a range of manual and automatic input devices.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 175),
  ('cambridge-0059', '3CS.04', 'Know that different types of file can be stored on a computer''s hard drive, including text, audio, image, video and games.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 176),
  ('cambridge-0059', '3CS.05', 'Know that computers can be programmed to control machines and other physical objects.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 177),
  ('cambridge-0059', '3CS.06', 'Identify common ''Internet of Things'' devices in a familiar environment.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 178),
  ('cambridge-0059', '3CS.07', 'Explain the role of robots in manufacturing.', 'en', '3', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 22', 179),
  ('cambridge-0072', '3TC.01', 'Compose, share, read and respond to online messages with appropriate individuals and groups.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Explore messaging systems in platforms that are available and that have appropriate safeguards in place. Other guidance: Potential activities include: • matching given messages to contexts • exploring and/or correcting messages that contain content that is inappropriate to the context • responding to diverse contexts with new messages and/or responses.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 180),
  ('cambridge-0072', '3TC.02', 'Explore how links, such as hyperlinks and QR codes, work and describe each platform type they send the user to.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: hyperlink, QR code Expectation: Recognise where links and QR codes exist, their purposes and the fact that they can link to a range of platform types. Other guidance: Exploration topics include: • what works well or less well • what adds or detracts from the experience of following the original artefact • adding, and testing, links to new artefacts.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 181),
  ('cambridge-0072', '3TC.03', 'Identify and explore spell-checking and proofreading tools within text processing software.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Develop a range of text-checking skills to produce outputs that demonstrate increasing accuracy. Other guidance: Learners are likely to begin by editing text that contains obvious errors before they apply their explorations to refining their own work.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 182),
  ('cambridge-0072', '3TC.04', 'Use devices to create simple multimedia artefacts, such as including two items in different modes.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: When combining modes, such as text with an image, demonstrate a relationship between the two items.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 183),
  ('cambridge-0072', '3TC.05', 'Edit images by changing colour and size, and by cropping, exploring both digital software and AI.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Explore this in a manner that is appropriate to the software that is available. Ideally, explore more than one platform and compare the experiences. Other guidance: Learning could be combined with adding images to other documents. Explorations include: • manual editing, using software • prompting AI to edit given images • reflections on the manual and AI experiences and outcomes.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 184),
  ('cambridge-0072', '3TC.06', 'Explore how entering text and verbal information requests into GenAI tools can form a progressive dialogue, rather than being a series of refined individual searches.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Begin to recognise that they do not need to re-start their prompting process in order to generate a refined output. Compare this with using a search engine, where each new prompt does start a new process.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 185),
  ('cambridge-0072', '3TC.07', 'Analyse the quality, relevance and accuracy of AI-generated text and media, identifying areas for improvement through further prompting.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Compare AI outputs with the intention to identify broad gaps in the initial prompt, rather than planning prompts in detail at this stage.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 186),
  ('cambridge-0072', '3TC.08', 'Explore creating prompts to produce detailed outputs, such as longer pieces of text.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Begin to progress from seeking single dimension ‘answers’ to more detailed information about a topic. Other guidance: Explorations include: • adding increasing detail and layers to prompts • prompting for descriptions and explanations, etc. • setting parameters, such as word count limits.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 187),
  ('cambridge-0072', '3TC.09', 'Explore the use of search functions to find artefacts within a storage structure.', 'en', '3', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Explore file structures, such as the school network, possibly in a treasure hunt scenario. Other guidance: Include prior knowledge recall related to common icons.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 188),
  ('cambridge-0072', '3SW.01', 'Know that device use and online activity can be monitored, and understand that this poses risks to personal data.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Recall prior knowledge that devices and platforms gather data from each interaction. Focus on examples such as name and date of birth. Consider scenarios where it is likely to be safe or unsafe to share this information. Other guidance: An acceptable example would be where streaming platforms use date of birth data to make decisions about content that is and is not appropriate for a person to stream.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 189),
  ('cambridge-0072', '3SW.02', 'Compare and contrast examples of feeling safe and unsafe in physical and digital worlds, including with the language encountered.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Discuss using appropriate contexts in a supportive classroom environment. This may require intervention and one-to-one support if concerns arise. Other guidance: Reflections include: • feelings associated with being unsafe • how these feelings might occur during digital activity • how it is sometimes easier for a friend to identify that someone is feeling unsafe in physical contexts. Therefore, stopping and telling a trusted person is vital. Examples that could generate unwanted feelings include: • when a tool stops working as expected • when starting a new level of a favourite game • when a tool does not respond to a prompt as desired • when unexpected activity or contact occurs.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 190),
  ('cambridge-0072', '3SW.03', 'Identify the risks of sharing personal information with AI platforms.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Understand that tools store data and use that data to inform future outputs. Other guidance: Risk identification might include: • equating AI with real-world strangers • understanding that a tool cannot be asked to forget the shared information • recalling that AI learns from all of the data that it is given to produce other outputs • understanding that any concerns should be shared with a trusted adult.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 191),
  ('cambridge-0072', '3SW.04', 'Recognise the importance of monitoring and balancing screentime across applications, platforms and task types.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Understand that too much of one type of activity poses risks to wellbeing, safety, learning and development. Other guidance: This provides an early opportunity for learners to explore the personal responsibility they have for their digital activity. It includes recall of prior learning about active and passive digital engagement.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 192),
  ('cambridge-0072', '3SW.05', 'Explore strategies for safely engaging in online spaces, including in group chats, being aware that personal information and identifying photographs and/or videos should not be shared.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Develop collective strategies, which include allowing time for pause, reflection and critical thinking. Other guidance: This is likely to be viewed through appropriate, but extreme, scenarios where learners are given opportunities to identify risky behaviours. Critical evaluation of example social media profiles could provoke thinking about good and bad practices.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 193),
  ('cambridge-0072', '3SW.06', 'Recognise how different types of online content and interactions can affect emotions, and develop strategies to manage these impacts.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Include early strategies for responding to malicious or other negative content. Extend into other areas such as frustration related to gameplay. Other guidance: This learning progresses into content related to addiction in later years.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 194),
  ('cambridge-0072', '3SW.07', 'Understand the risk that some dialogue, video and images encountered online might be generated or altered using digital or AI tools and might not show real people or events.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Explore how AI outputs can be presented as representing real events. Begin to identify ways of thinking critically about media. Other guidance: Explorations include: • looking for evidence that content does, or does not, reflect real events • critical thinking about whether the film maker, photographer or reporter is likely to have been present in the situation from which the events have been depicted • critical thinking about the possible intention of the film maker, photographer or reporter.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 20', 195),
  ('cambridge-0072', '3SW.08', 'Analyse the personification of AI tools, recognising factors by which they can be identified as being machines.', 'en', '3', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Provide further opportunity for learners to understand that AI tools are not human, even where human characteristics, such as physical features or ways of speaking, have been built into the design. Other guidance: Considerations include: • features that developers have used to ‘humanise’ their tools, such as voice • factors that dehumanise the tools, such as their need for a power source, their limited range of output or expression, and their reliance on input • that, given their limitations, AI tools can never replace the benefits of interaction with other humans.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 196),
  ('cambridge-0072', '3DW.01', 'Explore how computers and their use have changed over time.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Take a local approach to the teaching, as computer use will change in different ways, and at different speeds, in different geographic contexts. Other guidance: Explorations might include: • using older devices, where available, to identify similarities and differences • role-playing pre-digital tasks • discussion with adults who have experienced key moments of digital change or disruption.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 197),
  ('cambridge-0072', '3DW.02', 'Identify roles that AI is taking in tasks that have traditionally been completed by humans.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Includes the important understanding that AI is a helper for, not usually a replacer of, human activity. Other guidance: Explorations might include map apps, streaming recommendations, voice assistants, predictive text and spellcheckers, with critical evaluation required throughout.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 198),
  ('cambridge-0072', '3DW.03', 'Identify differences between AI tools across contexts, understanding that different platforms use different algorithms and inputs, to produce different outputs.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: algorithm, input, output Expectation: Understand that AI does not work by magic. Tools follow rules and processes that were initially given to them by humans, and they can only use the input and output devices to which they are connected. Other guidance: Explore different types of tools in terms of: • the type of input that a tool needs • an example, high-level processing step that it might use • the range of output formats that it can produce.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 199),
  ('cambridge-0072', '3DW.04', 'Explore how modes, such as images, video, text and film, can change meanings in digital worlds.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: mode (in the context of a digital or AI output) Expectation: Use age-appropriate scenarios to consider how different modes might make humans respond in different ways. Other guidance: An example discussion of different modes could be based on the following: • Text – ‘the cat is hungry’ • Image – a thin, sad-looking cat • Video – a cat meowing at an empty bowl • Animation or emoji – a cat sitting like a human at a dinner table. Questions might include: • Which mode makes you most want to help the cat? • Which mode is the funniest? • Which mode is the easiest to ignore?', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 200),
  ('cambridge-0072', '3DW.05', 'Understand that online communication has changed the way people interact and has enabled online communities to exist.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: online community Expectation: Explore how distance and time are less of a barrier to communication due to digital development. Also explore how people can communicate beyond family or real friendship groups. For example, they might join a community based on a specific shared interest. Other guidance: As an activity, learners might design their own community, based on personal interest, and create the rules for that community.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 201),
  ('cambridge-0072', '3DW.06', 'Know that AI can repeat the data that it is given, can mix up that data in new ways, but that it does not understand the outputs that it produces.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Understand that AI cannot make decisions about what is right and wrong. Appreciate that the AI tool does not understand the context of the task, unless this has been fully expressed in the instruction. Other guidance: Explore giving an AI tool instructions to create images, progressing from depictions that are based on realism, such as ‘a cat sitting on a chair’, to the unreal, such as ‘a green cat that is shaped like a star, sitting on top of a cake’. Learners should understand that, although it produced both outputs, the AI tool is not able to understand that one is realistic while the other is not.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 202),
  ('cambridge-0072', '3DW.07', 'Explore the difference between big and small, or local and global, digital divides.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: digital divide Expectation: Understand that a digital divide is a difference that exists between people who have full access to digital technology and those who do not. Explore high level implications and causes of the divides. Understand that the divide is not binary and that different people are affected in different ways, and for different reasons. Other guidance: Example causes: wealth, infrastructure, demographics, personal choice, social pressures.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 203),
  ('cambridge-0072', '3DW.08', 'Explore digital divides as a global and local challenge, focussing on access to reliable devices and reliable internet connection.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Identify the causes and impacts of digital divides. Contrast those that are relevant locally with those that either impact other communities or have global relevance. Explore potential solutions to each cause and impact. Other guidance: Explore drawbacks caused by not having access to devices and, separately, by not having access to fast internet, such as for streaming. Also explore case studies, possibly of remote areas that have limited access to devices and connectivity.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 204),
  ('cambridge-0072', '3DW.09', 'Identify, compare and contrast the skills used in different digital activities, including gameplay, information searching and artefact creation.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Granularly explore diverse activities to identify the skills and thought processes that are used. Identify other digital and non-digital activities where the same skills are used or could be used.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 205),
  ('cambridge-0072', '3DW.10', 'Determine tasks that are suitable for AI and tasks that should not be delegated to AI.', 'en', '3', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Using appropriate contexts, categorise tasks as suitable or unsuitable for delegation. Other guidance: Specific considerations might relate to: • learning – such as when completing homework • cheating – such as when trying to move up to a new level in a game.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 21', 206),
  ('cambridge-0059', '4CT.01', 'Follow, understand, edit and correct algorithms that use repetition, including indefinite (forever) loops.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 207),
  ('cambridge-0059', '4CT.02', 'Follow, understand, edit and correct algorithms that use iteration, including count-controlled loops.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 208),
  ('cambridge-0059', '4CT.03', 'Understand that the use of repetition can make algorithms more concise.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 209),
  ('cambridge-0059', '4CT.04', 'Compare and contrast algorithms designed for the same task to determine which produces the outcome that is best suited to the purpose.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 210),
  ('cambridge-0059', '4CT.05', 'Predict the outcome of algorithms that contain repetition.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 211),
  ('cambridge-0059', '4CT.06', 'Understand that decomposition is a process that is used to break tasks into different parts (sub-routines).', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 212),
  ('cambridge-0059', '4CT.07', 'Know how to use decomposition to break tasks into different parts, represented as algorithms.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 213),
  ('cambridge-0059', '4CT.08', 'Follow and understand algorithms that use a sub-routine.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 214),
  ('cambridge-0059', '4CT.09', 'Know how to develop algorithms to produce different outputs based on different inputs.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 215),
  ('cambridge-0059', '4CT.10', 'Know how to develop algorithms that include repetition.', 'en', '4', 'CT', 'Computational Thinking', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 23', 216),
  ('cambridge-0059', '4P.01', 'Know how to add comments to blocks of code and explain the benefits of these comments.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 217),
  ('cambridge-0059', '4P.02', 'Know how to develop programs with repetition.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 218),
  ('cambridge-0059', '4P.03', 'Know how to develop programs with iteration.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 219),
  ('cambridge-0059', '4P.04', 'Know how to develop programs that produce a desired output, which includes the use of the repeat command.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 220),
  ('cambridge-0059', '4P.05', 'Know how to develop programs that produce different outputs from different inputs.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 221),
  ('cambridge-0059', '4P.06', 'Know how to plan the instructions for objects within programs, including identifying inputs and outputs.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 222),
  ('cambridge-0059', '4P.07', 'Know how to test different parts of a program systematically, to identify and debug errors.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 223),
  ('cambridge-0059', '4P.08', 'Know how to develop programs for a physical computing device to produce outputs from input devices.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 224),
  ('cambridge-0059', '4P.09', 'Know how to develop programs for a physical computing device using count-controlled and indefinite (forever) loops.', 'en', '4', 'P', 'Programming', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 225),
  ('cambridge-0059', '4MD.01', 'Understand the differences between physical (paper-based) and digital databases.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 226),
  ('cambridge-0059', '4MD.02', 'Understand the advantages and disadvantages of using forms when collecting data.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 227),
  ('cambridge-0059', '4MD.03', 'Identify the differences between data and information.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 228),
  ('cambridge-0059', '4MD.04', 'Know how to sort data into a required order, including descending or ascending numerical values and alphabetically.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 229),
  ('cambridge-0059', '4MD.05', 'Identify appropriate data types for a field within a data table.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 230),
  ('cambridge-0059', '4MD.06', 'Know how to use a database to answer a single question.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 231),
  ('cambridge-0059', '4MD.07', 'Identify data, records and fields within a data table.', 'en', '4', 'MD', 'Managing Data', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 24', 232),
  ('cambridge-0059', '4DC.01', 'Explain the role of servers and clients in a network.', 'en', '4', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 233),
  ('cambridge-0059', '4DC.02', 'Describe the differences between the World Wide Web and the internet.', 'en', '4', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 234),
  ('cambridge-0059', '4DC.03', 'Describe the differences between wi-fi and ethernet, including speed, security and the use of wires.', 'en', '4', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 235),
  ('cambridge-0059', '4DC.04', 'Identify issues that may occur as a result of a failure in a network.', 'en', '4', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 236),
  ('cambridge-0059', '4DC.05', 'Identify where and why encryption is used in digital systems.', 'en', '4', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 237),
  ('cambridge-0059', '4DC.06', 'Know how to write and decode messages using the Caesar Cipher and the Pigpen Cipher.', 'en', '4', 'DC', 'Networks and Digital Communication', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 238),
  ('cambridge-0059', '4CS.01', 'Identify examples where a control system is used.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 239),
  ('cambridge-0059', '4CS.02', 'Know the functions of application and systems software.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 240),
  ('cambridge-0059', '4CS.03', 'Identify a range of data recorded by input devices in computer systems, including data that is collected through sensors and data loggers.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 241),
  ('cambridge-0059', '4CS.04', 'Identify a range of information communicated by output devices in computer systems.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 242),
  ('cambridge-0059', '4CS.05', 'Identify that different types of file have different sizes, including text, audio, image, video and games.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 243),
  ('cambridge-0059', '4CS.06', 'Describe the role of computer scientists in a range of industries.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 244),
  ('cambridge-0059', '4CS.07', 'Identify the role of robots in service industries, including for delivery services, public transport and health care.', 'en', '4', 'CS', 'Computer Systems', '[]'::jsonb, NULL, 'Cambridge Primary Computing 0059, Curriculum Framework (September 2021), p. 25', 245),
  ('cambridge-0072', '4TC.01', 'Identify that web pages have addresses, known as URLs, and know how to bookmark these, including saving them as ‘favourites’.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: URL, bookmark, favourite Expectation: Requires practical experience of bookmarking and recalling preferred sites, ideally across different devices and platforms. Other guidance: This could be explored through learners’ preferred websites, including matching the site name and description with the URL.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 246),
  ('cambridge-0072', '4TC.02', 'Explore a range of text creation tools, including typing and speech to text, and compare the outputs for accuracy.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Build on prior explorations of text creation tools. Important considerations when comparing tools are accuracy, speed and ease of use. Other guidance: Creating longer texts provides opportunities for identifying efficiencies and platform suitability in different contexts.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 247),
  ('cambridge-0072', '4TC.03', 'Use devices to create multimedia artefacts.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: multimedia Expectation: Broaden knowledge of combining two or more media types, possibly in presentation software. Other guidance: Media combinations might include text, images, audio, video and simple slide transitions or text animations.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 248),
  ('cambridge-0072', '4TC.04', 'Explore adding links within digital artefacts, including testing the functionality.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Expectation: Requires practical experience of copying URLs, adding them as links within different text and multimedia platforms, and then checking that the links function. Other guidance: Checking the links supports understanding of the need to check many aspects of multimedia outputs throughout a development process.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 249),
  ('cambridge-0072', '4TC.05', 'Apply critical literacy skills to compare and contrast AI-generated text with trusted sources, to identify evidence of credibility and unreliability.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: critical literacy Expectation: When evaluating AI-generated information, have a clear definition of what a ‘trusted source’ is, and understand that AI itself is not a trusted source.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 250),
  ('cambridge-0072', '4TC.06', 'Explore ways of refining AI prompts, for example by adding constraints.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: constraint Expectation: Focus on refining prompts based on combinations of output reflection and new intentions or instruction. Other guidance: Example constraints include setting a word count limit, date ranges or geographic regions for text, or specific colours for images and/or diagrams.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 251),
  ('cambridge-0072', '4TC.07', 'Explore creating specific prompts to produce outputs that have clear parameters.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: parameter Expectation: Based on prior critical thinking and prompt evaluation, explore how parameters can be applied at the outset of, and during, a prompting process.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 252),
  ('cambridge-0072', '4TC.08', 'Understand the importance of critically comparing AI outputs with the intention, and with the prompt.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: prompt Expectation: Recall prior knowledge of prompting and introduce critical evaluation of AI outputs. Other guidance: This is likely to include reflection and exploration of how prompts can be improved.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 253),
  ('cambridge-0072', '4TC.09', 'Explore downloading documents and files from appropriate sources, and save these for future use.', 'en', '4', 'TC', 'Tools and Content Creation', '[]'::jsonb, 'Vocabulary: download Expectation: Combine prior knowledge of file saving and trusted sources. Other guidance: Explore examples of what makes a file source appropriate or inappropriate across different media, such as information text, games, images and music. These considerations include whether downloads are allowed, such as the legitimacy of the source, i.e. whether it is likely to be the true owner of the data.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 254),
  ('cambridge-0072', '4SW.01', 'Identify the benefits of different platforms having different logon methods, including facial recognition or specific password structures.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Develop awareness that logon methods differ across platforms. Explore how different platforms have different security requirements and risks. Other guidance: Benefits include risk spread where one password is breached, and password re-setting options such as those using email or text message across platforms.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 255),
  ('cambridge-0072', '4SW.02', 'Understand that treating others with respect, and being respected, is of equal importance online as it is during face-to-face interaction.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Compare face-to-face with virtual interaction, including the value of pausing before responding in each. Other guidance: Consider the possibility that textual messages are not automatically seen by others and therefore require the recipient to alert a trusted adult when concerning content is received.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 256),
  ('cambridge-0072', '4SW.03', 'Describe what happens to archival data online, including how it is hard to remove and is at risk of being shared with unintended audiences.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Consider risks that information and opinion shared in personal conversation creates a digital record that can be shared further, including with, and without, malicious intent.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 257),
  ('cambridge-0072', '4SW.04', 'Understand that ''free'' online services often involve data collection as an alternative form of payment.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Explore potential development purposes for free online content, such as how indirect marketing might facilitate direct marketing. Other guidance: Learners might audit their interactions with ‘free’ platforms and identify the data that they share when doing so. This supports understanding that data such as their location, the amount of time they spend on a platform and where they navigate from and to can be tracked for a range of purposes.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 258),
  ('cambridge-0072', '4SW.05', 'Evaluate the benefits and risks of online anonymity to all parties involved in an interaction.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Explore the need for balance. Personal data can be protected through anonymity, but anonymity can also diminish a person’s sense of responsibility. Other guidance: Give critical evaluation to whether an anonymous source can be a trusted source.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 259),
  ('cambridge-0072', '4SW.06', 'Develop strategies for deciding where to devote screentime and to set limits.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Recall prior knowledge about benefits and drawbacks of different activity types before this is gathered together and developed into personal, reasoned strategies. Other guidance: Learners might create personal time ratios for how long is reasonable to spend on each of their regular digital activities, including relaxation. This includes consideration of times of the day that are better suited to different activity types.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 260),
  ('cambridge-0072', '4SW.07', 'Explore the emotional benefits of shared screentime.', 'en', '4', 'SW', 'Safety, Wellbeing and Responsibility', '[]'::jsonb, 'Expectation: Explore opportunities for communication, friendship, collaboration and enjoyment when using a range of platforms. Other guidance: This is an opportunity to counterbalance negative reflections on aspects of digital activity, including gaming. Give consideration to how shared experiences are more beneficial than solitary ones.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 22', 261),
  ('cambridge-0072', '4DW.01', 'Explore how AI has contributed substantially to the speed and impact of digital development.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Understand that change is happening now, rather than being restricted to the past. Other guidance: Learners might identify changes from personal experience. Understanding could also be supported through timelining, with input from teachers, other adults and research.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 262),
  ('cambridge-0072', '4DW.02', 'Identify roles that AI is taking in tasks that have traditionally been completed by other machines, including in automated processes and in digital games.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: automated process, automation Expectation: Understand that AI is replacing other machines and technology, as well as human activity. Other guidance: This can be explored in contexts such as: • industrial practices, where AI has increasing levels of control over robots • gaming, by contrasting the responses of computer-controlled, opponent characters in older games with newer, responsive games.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 263),
  ('cambridge-0072', '4DW.03', 'Discuss how the speed of AI integration reduces the availability of facts when analysing its benefits and drawbacks.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Include exploration of contexts where humans have learned from history to inform new developments and practices. Also include risk analysis related to AI deployment, including how this generates human anxiety.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 264),
  ('cambridge-0072', '4DW.04', 'Explore contexts where one mode is more important than another and how that impacts digital worlds.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Evaluate different modes in different contexts, for example, needing detail, needing a main message quickly, needing clarity, needing to have attention grabbed. Evaluate which modes are likely to be most important in each context. Other guidance: This can be explored through scenarios such as a contrast between the mode used for communicating an emergency and that used for detailed explanation of an issue or solution.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 265),
  ('cambridge-0072', '4DW.05', 'Explore how people create online content for specific purposes, such as advertising, expressing opinions, and sharing information.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Include critical thinking about the purposes of a range of online content. Also explore ‘trusted sources’ further, including whether advertisers and influencers can be trusted to tell the truth about the products that they are being paid to promote.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 266),
  ('cambridge-0072', '4DW.06', 'Understand that AI tools are all machine-based systems and do not have emotions and self-regulation skills in the same way as humans.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Explore reasons why an AI developer might seek to humanise their products. Focus on emotions, such as where an AI tool has been programmed to play a game to win, without being able to recognise the emotional impact that this is having on its human opponent. Other guidance: With reference to cookies, learners understand that the AI assistants in their home do not keep secrets from other networked devices.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 267),
  ('cambridge-0072', '4DW.07', 'Know that cookies are data files that store information about online activity, which is then used for a range of purposes.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: cookies Expectation: Include understanding that the data held by cookies is permanent and is increased through each online activity. Understand that a trusted adult should be consulted before responding ‘yes’ to an onscreen question that is not expected or fully understood. Explore ‘essential’ and ‘non-essential’ cookies. Other guidance: Understanding might align cookies with unremovable badges or tattoos that list personal information, such as interests and languages spoken.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 268),
  ('cambridge-0072', '4DW.08', 'Evaluate applications of AI, including time saving, removing the need for repetitive human activity, working in hazardous environments, and reducing the risk of human error.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Consider positives and negatives, including risks and opportunities related to employment. Other guidance: Local context, such as local industries, is valuable here.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 269),
  ('cambridge-0072', '4DW.09', 'Explore causes of local digital divides, including affordability, confidence, health, education, trust and personal choice.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Vocabulary: digital divide Expectation: Understand that, at an individual level, there can be many reasons why some people are less able to access the digital world. Other guidance: This appreciation could extend to understanding how barriers such as confidence or health can then be increased through lack of access.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 270),
  ('cambridge-0072', '4DW.10', 'Compare and contrast AI with human intelligence to differentiate machine and human forms of intelligence.', 'en', '4', 'DW', 'The Digital World', '[]'::jsonb, 'Expectation: Understand that AI tools should be used to support, rather than replace, human intelligence. Other guidance: This could be covered in different learning contexts, such as: • In mathematics, AI can solve complex arithmetic really quickly but humans understand why it is being solved. • In art, AI can mix many existing styles and ideas but humans can create something entirely new from their imagination.', 'Cambridge Primary Digital Literacy 0072, Curriculum Framework v3.0 (February 2026), p. 23', 271)
