-- Migration 0059: curriculum framework catalogue (docs/lesson-engine/README.md,
-- "Framework catalogue"). A read-only reference of the documents Rozumko
-- skills map to: the national standard's informatics results (NUSH, edition in
-- force, framework key nush-ifo-2018) and Cambridge Primary Computing 0059 and
-- Digital Literacy 0072, Stages 1-4, with their official wording, strands, MON
-- task examples and Cambridge guidance.
--
-- Evidence never targets these rows: it is written against Rozumko skills
-- (curriculum_outcomes), which name a catalogue entry in `mappings`
-- ({framework, ref: code}). Admin-only, like the outcome directory: Cambridge
-- wording is licensed material and never reaches teachers, students or
-- public bundles. RLS on, no policies. Data is inserted once (ON CONFLICT DO
-- NOTHING); a wording fix is a new migration.
-- Generated from temp/objectives (271 rows).

CREATE TABLE IF NOT EXISTS public.curriculum_framework_refs (
  framework text NOT NULL,
  code text NOT NULL,
  title text NOT NULL,
  lang text NOT NULL,
  level text NOT NULL,
  group_code text,
  group_title text,
  examples jsonb NOT NULL DEFAULT '[]'::jsonb,
  guidance text,
  source text NOT NULL,
  sort_order integer NOT NULL,
  PRIMARY KEY (framework, code),
  CONSTRAINT curriculum_framework_refs_framework_check CHECK (framework ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT curriculum_framework_refs_title_check CHECK (length(btrim(title)) > 0),
  CONSTRAINT curriculum_framework_refs_lang_check CHECK (lang IN ('uk', 'en')),
  CONSTRAINT curriculum_framework_refs_examples_check CHECK (jsonb_typeof(examples) = 'array')
);

CREATE INDEX IF NOT EXISTS curriculum_framework_refs_order_idx
  ON public.curriculum_framework_refs (framework, sort_order);

ALTER TABLE public.curriculum_framework_refs ENABLE ROW LEVEL SECURITY;

ON CONFLICT (framework, code) DO NOTHING;
